pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: call SetMinSum(5), SetLogFile(address(0)), Initialized
        // The reference's SetMinSum reverts if initialized is false, but here we call before Initialized
        c.SetMinSum(5);
        c.SetLogFile(address(0));
        c.Initialized();

        // Deposit 10 wei
        vm.deal(address(this), 10);
        c.Deposit{value: 10}();

        // Collect 5 wei (MinSum is 5, balance is 10, so condition holds)
        // Before Collect, the reference's SetMinSum does nothing because initialized is true,
        // but the buggy version's SetMinSum is called here? No, we never call SetMinSum again.
        // Actually the difference is about what happens if SetMinSum were called after Initialized.
        // Let's re-think: The buggy version's SetMinSum always sets MinSum to _val regardless of initialized.
        // So if we call SetMinSum with a different value after Initialized, the buggy version would change it.
        // We need to trigger that path.
        // So call SetMinSum(10) again after Initialized, then Collect.
        c.SetMinSum(10); // In reference, this reverts because intitalized is true; in buggy, it succeeds and sets MinSum=10.

        // Now Collect(5) — buggy version will have MinSum=10, so condition (balances >= MinSum?) fails because balance=10, MinSum=10, OK it passes.
        // Actually balance=10, MinSum=10, _am=5 => condition holds.
        // Wait, we need observable difference. Let's compute:
        // Reference: after SetMinSum(10) reverts, the revert means the transaction is rolled back.
        // So we need to wrap in try/catch.
        // Actually, the revert in SetMinSum will cause the whole transaction to revert, so we can't continue.
        // Better: Call SetMinSum(10) in a separate transaction; reference fails, buggy succeeds.
        // But then the test must handle the revert. So we try/catch the SetMinSum call.
        bool ok;
        try c.SetMinSum(10) {
            ok = true;
        } catch {
            ok = false;
        }
        // Now the reference has ok=false, buggy has ok=true.
        // We assert that ok is false (reference behavior).
        assertTrue(!ok);
    }
}

