    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 10
        c.SetMinSum(10);
        // Initialize the contract
        c.Initialized();
        // Fund alice with 10 wei
        address alice = address(0x1234);
        vm.deal(alice, 10);
        vm.prank(alice);
        c.Deposit{value: 10}();
        // Now alice's balance = 10, MinSum = 10
        // Correct contract: Collect(1) requires balances[alice] >= MinSum (10 >= 10) AND balances[alice] >= _am (10 >= 1) -> true, then subtracts 1 -> balance = 9
        // Buggy contract: condition becomes balances >= MinSum OR balances >= _am -> true, same behavior expected initially
        // After subtraction, balance = 9. Now correct contract: balances[alice] = 9 < MinSum (10), so Collect(1) requires false (9 >= 10 false AND 9 >= 1 true) -> false -> revert
        // Buggy contract: OR condition: 9 >= 10 false OR 9 >= 1 true -> true -> allows withdrawal
        vm.prank(alice);
        c.Collect(1); // first withdrawal, both contracts succeed
        // second withdrawal attempt
        bool ok;
        vm.prank(alice);
        try c.Collect(1) { ok = true; } catch { ok = false; }
        // Correct contract: reverts (ok = false); buggy contract: succeeds (ok = true)
        assertTrue(!ok); // reference passes (reverts), bug fails (doesn't revert)
    }
}

