    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: Alice address
        address alice = address(0x1234);
        vm.deal(alice, 10 wei);

        // Initialize the contract
        c.SetMinSum(10 wei);

        // Alice deposits 10 wei
        vm.prank(alice);
        c.Deposit{value: 10 wei}();

        // Now try Collect(1) - should revert in correct, succeed in buggy
        bool ok;
        try c.Collect(1) { ok = true; } catch { ok = false; }

        // In the correct contract, Collect should revert because after subtracting 1 wei,
        // balance would be 9 wei, which is < MinSum (10 wei), so the && fails.
        // In the buggy contract, the || allows because balance >= 1 wei.
        assertTrue(!ok, "Reference should revert, buggy should succeed");
    }
}

