pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: Alice deposits 5 ether, MinSum = 10 ether
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);

        // Alice deposits 5 ether
        vm.prank(alice);
        c.Deposit{value: 5 ether}();

        // Set MinSum to 10 ether
        c.SetMinSum(10 ether);
        c.Initialized();

        // Attempt Collect(5) from Alice
        vm.prank(alice);
        bool ok;
        try c.Collect(5 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // In correct contract: balances[alice] = 5 ether < MinSum = 10 ether, so Collect reverts => ok = false
        // In buggy contract: balances[alice] = 5 ether >= _am = 5 ether (OR condition), so Collect succeeds => ok = true
        assertTrue(!ok, "Correct contract should revert, buggy contract should not");
    }
}
